mapper.select:
SELECT EXISTS (
    SELECT 1 FROM sales_user WHERE email = #{email}
)

SELECT EXISTS (
    SELECT 1 FROM sales_user WHERE phone = #{phone}
)

SELECT su.id, su.employee_id AS employeeId, su.name, su.status_code AS statusCode, cc.code_name AS statusName, ( (SELECT COUNT(DISTINCT pc.id) FROM potential_customer pc WHERE pc.sales_user_id = su.id) + (SELECT COUNT(DISTINCT ic.integrated_customer_id) FROM integrated_customer ic WHERE ic.sales_user_id = su.id) ) AS customerCount FROM sales_user su LEFT JOIN common_code cc ON cc.group_code = 'USER_STATUS' AND cc.code_value = su.status_code
AND (su.name LIKE CONCAT('%', #{keyword}, '%') OR su.employee_id LIKE CONCAT('%', #{keyword}, '%'))
AND su.status_code = #{statusCode}
ORDER BY su.id DESC LIMIT #{safeSize} OFFSET #{offset}

SELECT COUNT(1) FROM sales_user su
AND (su.name LIKE CONCAT('%', #{keyword}, '%') OR su.employee_id LIKE CONCAT('%', #{keyword}, '%'))
AND su.status_code = #{statusCode}
